#include <bits/stdc++.h>
using namespace std;using V=array<int,5>;using M=array<V,5>;using Bits=array<uint64_t,4>;
V mv(const M&A,const V&v){V w{};for(int i=0;i<5;i++){for(int j=0;j<5;j++)w[i]+=A[i][j]*v[j];w[i]%=3;}return w;}
vector<V> rref(vector<V>a){int k=0;for(int j=0;j<5;j++){int p=k;while(p<(int)a.size()&&!a[p][j])p++;if(p==(int)a.size())continue;swap(a[k],a[p]);int z=a[k][j];for(int i=0;i<5;i++)a[k][i]=a[k][i]*z%3;for(int p=0;p<(int)a.size();p++)if(p!=k){int z=a[p][j];for(int i=0;i<5;i++)a[p][i]=(a[p][i]-z*a[k][i]+6)%3;}if(++k==(int)a.size())break;}a.resize(k);return a;}
V red(V v,const vector<V>&C){for(auto row:C){int p=0;while(!row[p])p++;int z=v[p];for(int j=0;j<5;j++)v[j]=(v[j]-z*row[j]+6)%3;}int p=0;while(p<5&&!v[p])p++;if(p<5){int z=v[p];for(int j=0;j<5;j++)v[j]=v[j]*z%3;}return v;}
int code(V v){int z=0,p=1;for(int j=0;j<5;j++){z+=p*v[j];p*=3;}return z;}
Bits space(vector<V>bs){bs=rref(bs);vector<V>vs(1);for(auto b:bs){int n=vs.size();for(int l=1;l<3;l++)for(int i=0;i<n;i++){V z=vs[i];for(int j=0;j<5;j++)z[j]=(z[j]+l*b[j])%3;vs.push_back(z);}}Bits z{};for(auto v:vs){int k=code(v);z[k/64]|=1ull<<(k%64);}return z;}
vector<int> reducew(const vector<int>&w){vector<int>z;for(int t:w){if(!z.empty()&&z.back()==t)z.pop_back();else z.push_back(t);}return z;}
struct WData{vector<int>w;vector<V>core;int mp[4][121];vector<V>qv;vector<Bits>pair;int sz;unsigned baseMask=0;};
struct Constraint{int type,kind;array<int,4>state;vector<array<int,4>>paths;};
int main(int ac,char**av){if(ac<7)return 1;string inp=av[1],adjp=av[2],out=av[3];int seed=atoi(av[4]),initial=atoi(av[5]);double secs=atof(av[6]),Tmax=ac>7?atof(av[7]):50;ifstream f(inp),g(adjp);M A[4];V b[4];for(auto&M:A)for(auto&r:M)for(int&x:r)f>>x;for(auto&v:b)for(int&x:v)f>>x;vector<array<int,4>>C;array<int,4>row;while(g>>row[0]>>row[1]>>row[2]>>row[3])C.push_back(row);int n=C.size();
vector<V>dirs;vector<int>dcodes;for(int v=1;v<243;v++){V d{};int z=v;for(int j=0;j<5;j++){d[j]=z%3;z/=3;}int p=0;while(!d[p])p++;if(d[p]==1){dirs.push_back(d);dcodes.push_back(v);}}assert(dirs.size()==121);
auto control=[&](vector<int>w){vector<V>cs;for(int t:w){for(auto&v:cs)v=mv(A[t],v);cs.push_back(b[t]);}return rref(cs);};
vector<WData>rd3,wd1;vector<vector<int>>w3;for(int k=0;k<64;k++){int z=k;vector<int>w(3);for(int j=0;j<3;j++){w[j]=z%4;z/=4;}auto r=reducew(w);if(r.size()==3){WData d;d.w=w;d.core=control(w);rd3.push_back(d);}else {WData d;d.w=w;d.core=control(w);wd1.push_back(d);}}
for(auto*data:{&rd3,&wd1})for(auto &d:*data){map<V,int>ids;V zero{};ids[zero]=0;d.qv.push_back(zero);for(int pos=0;pos<4;pos++)for(int ci=0;ci<121;ci++){V v=dirs[ci];for(int j=pos;j<3;j++)v=mv(A[d.w[j]],v);v=red(v,d.core);if(!ids.count(v)){ids[v]=d.qv.size();d.qv.push_back(v);}d.mp[pos][ci]=ids[v];}d.sz=d.qv.size();if(data==&wd1){d.pair.resize(d.sz*d.sz);for(int x=0;x<d.sz;x++)for(int y=0;y<d.sz;y++){auto bs=d.core;bs.push_back(d.qv[x]);bs.push_back(d.qv[y]);d.pair[x*d.sz+y]=space(bs);}}}
Bits base1[4]{};
for(int k=0;k<1024;k++){int z=k;vector<int>w(5);for(int j=0;j<5;j++){w[j]=z%4;z/=4;}auto r=reducew(w);if(r.size()==1){auto bs=space(control(w));for(int j=0;j<4;j++)base1[r[0]][j]|=bs[j];}if(r.size()==3){auto it=find_if(rd3.begin(),rd3.end(),[&](auto&d){return d.w==r;});auto cs=control(w);for(auto v:cs){v=red(v,it->core);if(v!=V{}){int p=find(it->qv.begin(),it->qv.end(),v)-it->qv.begin();assert(p<it->sz);it->baseMask|=1u<<p;}}}}
vector<vector<int>>family(4);for(int i=0;i<(int)wd1.size();i++)family[reducew(wd1[i].w)[0]].push_back(i);for(auto&d:rd3)assert(__builtin_popcount(d.baseMask)==2);
vector<Constraint>con;vector<vector<int>>deps(n);auto path=[&](int u,vector<int>w){array<int,4>s;s[0]=u;for(int j=0;j<3;j++)s[j+1]=C[s[j]][w[j]];return s;};
for(int u=0;u<n;u++){for(int r=0;r<36;r++){Constraint cc;cc.type=3;cc.kind=r;cc.state=path(u,rd3[r].w);con.push_back(cc);}for(int t=0;t<4;t++){Constraint cc;cc.type=1;cc.kind=t;for(int wi:family[t])cc.paths.push_back(path(u,wd1[wi].w));con.push_back(cc);}}
for(int i=0;i<(int)con.size();i++){set<int>ss;if(con[i].type==3){for(int u:con[i].state)ss.insert(u);}else for(auto s:con[i].paths)for(int u:s)ss.insert(u);for(int u:ss)deps[u].push_back(i);}
mt19937_64 rng(seed);vector<int>cs(n);for(auto &x:cs)x=initial?find(dcodes.begin(),dcodes.end(),initial)-dcodes.begin():rng()%121;
auto eval=[&](int j){auto &c=con[j];if(c.type==3){auto&d=rd3[c.kind];unsigned mask=0;for(int p=0;p<4;p++){int z=d.mp[p][cs[c.state[p]]];if(z)mask|=1u<<z;}if(__builtin_popcount(mask)>=2)return 0;return 243-27*(1+2*__builtin_popcount(mask|d.baseMask));}
 Bits bits=base1[c.kind];int z=0;for(int wi:family[c.kind]){auto &d=wd1[wi];auto states=c.paths[z++];int p[4];for(int t=0;t<4;t++)p[t]=d.mp[t][cs[states[t]]];for(int t=0;t<4;t++)for(int h=t+1;h<4;h++){auto bs=d.pair[p[t]*d.sz+p[h]];for(int k=0;k<4;k++)bits[k]|=bs[k];}if(bits[0]==~0ull&&bits[1]==~0ull&&bits[2]==~0ull&&bits[3]==((1ull<<51)-1))return 0;}int cnt=0;for(auto x:bits)cnt+=__builtin_popcountll(x);return 243-cnt;};
vector<int>cv(con.size());int val=0;for(int j=0;j<(int)con.size();j++)val+=cv[j]=eval(j);int best=val;auto bestC=cs;long long steps=0,acc=0;auto start=chrono::steady_clock::now();auto save=[&](){ofstream f(out+".json");f<<"{\"n\":"<<n<<",\"seed\":"<<seed<<",\"steps\":"<<steps<<",\"missing_short_route_points\":"<<best<<",\"direction_codes\":[";for(int i=0;i<n;i++)f<<(i?",":"")<<dcodes[bestC[i]];f<<"],\"seconds\":"<<chrono::duration<double>(chrono::steady_clock::now()-start).count()<<"}";};save();cerr<<"START "<<best<<" n "<<n<<" basecounts ";for(auto bs:base1){int z=0;for(auto x:bs)z+=__builtin_popcountll(x);cerr<<z<<' ';}cerr<<'\n';
vector<int>nv;for(steps=0;steps<100000000;steps++){if(steps%1000==0&&chrono::duration<double>(chrono::steady_clock::now()-start).count()>secs)break;int u=rng()%n;if(rng()%3!=0){int ci=rng()%con.size();for(int k=0;k<20&&cv[ci]==0;k++)ci=rng()%con.size();auto &z=con[ci];u=z.type==3?z.state[rng()%4]:z.paths[rng()%7][rng()%4];}int old=cs[u],fresh=rng()%121;if(old==fresh)continue;cs[u]=fresh;int delta=0;nv.clear();for(int ci:deps[u]){int z=eval(ci);nv.push_back(z);delta+=z-cv[ci];}double T=.05+Tmax*pow(.002,(steps%100000)/100000.);if(delta<=0||uniform_real_distribution<double>(0,1)(rng)<exp(-delta/T)){val+=delta;acc++;for(int k=0;k<(int)deps[u].size();k++)cv[deps[u][k]]=nv[k];}else cs[u]=old;if(val<best){best=val;bestC=cs;save();cerr<<"BEST "<<best<<" step "<<steps<<'\n';if(!best)break;}if(steps%100000==99999){cs=bestC;val=0;for(int j=0;j<(int)con.size();j++)val+=cv[j]=eval(j);}}
save();cerr<<"DONE best "<<best<<" steps "<<steps<<" accepted "<<acc<<'\n';}
